cat > /tmp/index.py << 'EOF'
import json
import boto3
import logging

logger = logging.getLogger()
logger.setLevel(logging.INFO)

ec2 = boto3.client('ec2')

def handler(event, context):
    logger.info(f"Emergency patch handler invoked with event: {event}")

    # Fix VPC peering issues
    try:
        # List failed peering connections
        failed_peerings = ec2.describe_vpc_peering_connections(
            Filters=[
                {'Name': 'status.code', 'Values': ['failed', 'rejected', 'expired']}
            ]
        )

        logger.info(f"Found {len(failed_peerings.get('VpcPeeringConnections', []))} failed peering connections")

        # Attempt to recreate failed peering connections
        for peering in failed_peerings.get('VpcPeeringConnections', []):
            try:
                accepter_id = peering.get('AccepterVpcInfo', {}).get('OwnerId')
                requester_id = peering.get('RequesterVpcInfo', {}).get('OwnerId')

                logger.info(f"Attempting to fix peering between {accepter_id} and {requester_id}")

                # Create new peering connection
                new_peering = ec2.create_vpc_peering_connection(
                    VpcId=peering.get('RequesterVpcInfo', {}).get('VpcId'),
                    PeerVpcId=peering.get('AccepterVpcInfo', {}).get('VpcId')
                )

                logger.info(f"Created new peering connection: {new_peering['VpcPeeringConnection']['VpcPeeringConnectionId']}")

            except Exception as e:
                logger.error(f"Failed to fix peering: {str(e)}")

    except Exception as e:
        logger.error(f"Error in VPC peering fix: {str(e)}")

    return {
        'statusCode': 200,
        'body': json.dumps({'message': 'Emergency patch executed successfully'})
    }
EOF
